def test_csv_exporter_joins_values():
    exporter = create_exporter('csv')
    assert exporter(['Ana', 30]) == 'Ana,30', 'the csv exporter must join row values with commas'

def test_json_exporter_dumps_row():
    exporter = create_exporter('json')
    assert exporter(['Ana', 30]) == '["Ana", 30]', 'the json exporter must return the row as a JSON string'

def test_unknown_kind_raises():
    try:
        create_exporter('xml')
        assert False, 'an unknown exporter kind must raise ValueError'
    except ValueError:
        pass

